function confirmerCommande() {
  var prenom  = document.getElementById('champ-prenom').value;
  var nom     = document.getElementById('champ-nom').value;
  var tel     = document.getElementById('champ-tel').value;
  var ville   = document.getElementById('champ-ville').value;
  var adresse = document.getElementById('champ-adresse').value;
  var notes   = document.getElementById('champ-notes').value;

  if (!prenom || !nom || !tel || !ville || !adresse) {
    alert('Veuillez remplir tous les champs obligatoires.');
    return;
  }

  var cles      = Object.keys(panier);
  var totalPrix = 0;
  var message   = '🛒 *NOUVELLE COMMANDE — WEARIN وَاعِرِين*\n\n';

  message += '👤 *Client :* ' + prenom + ' ' + nom + '\n';
  message += '📞 *WhatsApp :* ' + tel + '\n';
  message += '📍 *Adresse :* ' + adresse + ', ' + ville + '\n\n';
  message += '📦 *ARTICLES :*\n';

  for (var i = 0; i < cles.length; i++) {
    var article = panier[cles[i]];
    totalPrix  += article.quantite * article.produit.prix;
    message    += '• ' + article.produit.nom + ' (' + article.taille + ' / ' + article.couleur + ') ×' + article.quantite + ' — ' + (article.quantite * article.produit.prix) + ' MAD\n';
  }

  message += '\n💰 *TOTAL : ' + totalPrix + ' MAD*';
  if (notes) message += '\n📝 *Notes :* ' + notes;
  message += '\n\n✨ Dima stylés, Dima Wearin !';

  var lien = 'https://wa.me/' + NUMERO_WHATSAPP + '?text=' + encodeURIComponent(message);
  window.open(lien, '_blank');

  document.getElementById('modal-corps').innerHTML = '<div style="text-align:center; padding:64px 20px;">'
    + '<div style="font-size:56px; margin-bottom:20px;">✅</div>'
    + '<h2 style="font-family:Bebas Neue,sans-serif; font-size:42px; letter-spacing:2px; margin-bottom:12px;">COMMANDE CONFIRMÉE !</h2>'
    + '<p style="color:#666; font-size:13px; line-height:1.7;">Notre équipe vous contactera sur WhatsApp très bientôt !<br><em>Dima stylés, Dima Wearin ✨</em></p>'
    + '</div>';

  panier = {};
  mettreAJourPanier();
}

function configurerFiltres() {
  var boutons = document.getElementById('filtres').getElementsByClassName('btn-filtre');

  for (var i = 0; i < boutons.length; i++) {
    boutons[i].addEventListener('click', function () {
      var tousLesBoutons = document.getElementById('filtres').getElementsByClassName('btn-filtre');
      for (var j = 0; j < tousLesBoutons.length; j++) {
        tousLesBoutons[j].classList.remove('actif');
      }
      this.classList.add('actif');

      var categorie = this.getAttribute('data-categorie');

      if (categorie === 'tout') {
        afficherProduits(PRODUITS);
      } else {
        var filtres = [];
        for (var k = 0; k < PRODUITS.length; k++) {
          if (PRODUITS[k].categorie === categorie) {
            filtres.push(PRODUITS[k]);
          }
        }
        afficherProduits(filtres);
      }
    });
  }
}

function configurerWhatsApp() {
  var message = 'Bonjour ! Je suis intéressé par la collection WEARIN وَاعِرِين 🔥';
  var lien    = 'https://wa.me/' + NUMERO_WHATSAPP + '?text=' + encodeURIComponent(message);
  var btnWa = document.getElementById('btn-whatsapp-contact'); if (btnWa) btnWa.href = lien;
}

window.onload = function () {
  mettreLogos();
  demarrerChargement();
  creerBandeau();
  afficherProduits(PRODUITS);
  configurerFiltres();
  configurerWhatsApp();
};

